    override fun deserialize(decoder: Decoder): Status {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        if (element is JsonPrimitive && element.isString) {
            return when (element.content) {
                "Pending" -> Status.Pending
                else -> throw SerializationException("Unknown Status variant " + element.content)
            }
        }
        val (key, payload) = element.jsonObject.entries.singleOrNull()
            ?: throw SerializationException("Unknown Status variant " + element)
        return when (key) {
            "Active" -> Status.Active(json.decodeFromJsonElement(serializer<Status_Active>(), payload))
            "Completed" -> Status.Completed(json.decodeFromJsonElement(serializer<Status_Completed>(), payload))
            else -> throw SerializationException("Unknown Status variant " + key)
        }
    }
}

