@Serializable(with = WireOutcomeSerializer::class)
sealed class WireOutcome {
    object Done : WireOutcome()

    data class Failed(val value: String) : WireOutcome()
}

internal object WireOutcomeSerializer : KSerializer<WireOutcome> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: WireOutcome) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            WireOutcome.Done -> JsonObject(mapOf("kind" to JsonPrimitive("Done")))
            is WireOutcome.Failed -> JsonObject(mapOf("kind" to JsonPrimitive("Failed"), "data" to json.encodeToJsonElement(serializer<String>(), value.value)))
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): WireOutcome {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        val fields = element.jsonObject
        val tag = fields["kind"]?.jsonPrimitive?.content
        return when (tag) {
            "Done" -> WireOutcome.Done
            "Failed" -> WireOutcome.Failed(json.decodeFromJsonElement(serializer<String>(), fields["data"] ?: JsonNull))
            else -> throw SerializationException("Unknown WireOutcome variant " + tag)
        }
    }
}

