@Serializable(with = WireShapeSerializer::class)
sealed class WireShape {
    object Rect : WireShape()

    data class Text(val value: WireShape_Text) : WireShape()
}

internal object WireShapeSerializer : KSerializer<WireShape> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: WireShape) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            WireShape.Rect -> JsonObject(mapOf("kind" to JsonPrimitive("rect")))
            is WireShape.Text -> JsonObject(json.encodeToJsonElement(serializer<WireShape_Text>(), value.value).jsonObject + ("kind" to JsonPrimitive("text")))
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): WireShape {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        val fields = element.jsonObject
        val tag = fields["kind"]?.jsonPrimitive?.content
        return when (tag) {
            "rect" -> WireShape.Rect
            "text" -> WireShape.Text(json.decodeFromJsonElement(serializer<WireShape_Text>(), JsonObject(fields - "kind")))
            else -> throw SerializationException("Unknown WireShape variant " + tag)
        }
    }
}

