@Serializable(with = WireStepSerializer::class)
sealed class WireStep {
    data class Retain(val value: WireStep_Retain) : WireStep()

    data class Insert(val value: WireStep_Insert) : WireStep()
}

internal object WireStepSerializer : KSerializer<WireStep> {
    override val descriptor: SerialDescriptor = JsonElement.serializer().descriptor

    override fun serialize(encoder: Encoder, value: WireStep) {
        val json = (encoder as JsonEncoder).json
        val element = when (value) {
            is WireStep.Retain -> json.encodeToJsonElement(serializer<WireStep_Retain>(), value.value)
            is WireStep.Insert -> json.encodeToJsonElement(serializer<WireStep_Insert>(), value.value)
        }
        encoder.encodeJsonElement(element)
    }

    override fun deserialize(decoder: Decoder): WireStep {
        val json = (decoder as JsonDecoder).json
        val element = decoder.decodeJsonElement()
        runCatching { WireStep.Retain(json.decodeFromJsonElement(serializer<WireStep_Retain>(), element)) }.getOrNull()?.let { return it }
        runCatching { WireStep.Insert(json.decodeFromJsonElement(serializer<WireStep_Insert>(), element)) }.getOrNull()?.let { return it }
        throw SerializationException("No WireStep variant matches " + element)
    }
}

@Serializable
data class WireStep_Insert(
    val insert: String,
)

@Serializable
data class WireStep_Retain(
    val retain: UInt,
)

